        if(age>=715&&age<975){for(var entity:mc.level.entitiesForRendering())if(entity instanceof me.cryo.zombierool.entity.ZombieEntity mob){String skin=mob.getCustomSkin();boolean ghoul=skin.endsWith("/1"),skeleton=skin.endsWith("/7"),zombie=skin.endsWith("/5");if(ghoul&&age<820){mob.deathTime=age<756?0:age==756?1:19;if(age<756){mob.walkAnimation.update(age<737?.3f:.75f,1);mob.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED).setBaseValue(age<737?.19:.25);}}if(skeleton&&age>=820&&age<900)mob.deathTime=age<835?0:age==835?1:19;if(zombie&&age>=900)mob.deathTime=age<915?0:age==915?1:19;}}
