    @SuppressWarnings({"rawtypes","unchecked"}) void verifyMotion(Minecraft mc)throws Exception{
        var constructor=me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model.class.getDeclaredConstructor(String.class);constructor.setAccessible(true);var field=me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model.class.getDeclaredField("bones");field.setAccessible(true);
        var clipField=me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model.class.getDeclaredField("clips");clipField.setAccessible(true);var hipField=me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model.class.getDeclaredField("hip");hipField.setAccessible(true);var originsField=me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model.class.getDeclaredField("origins");originsField.setAccessible(true);var actor=mc.player;
        for(String kind:new String[]{"pentagon_thief","george_romero","astronaut","abomination","geist","scourge_ghoul","scourge_zombie","scourge_skeleton"}){
            var model=(me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model)constructor.newInstance(kind);var bones=(java.util.Map<String,net.minecraft.client.model.geom.ModelPart>)field.get(model);var clips=(java.util.Map<?,?>)clipField.get(model);
            check(clips.containsKey("death")&&clips.containsKey("walk")&&clips.containsKey("melee"),"Original per-enemy clips are loaded: "+kind);
            float maximumStep=0;java.util.Map<String,org.joml.Quaternionf> previous=new java.util.HashMap<>();
            for(int i=0;i<300;i++){model.setupAnim(actor,i*.05f,.7f,actor.tickCount+i*.05f,0,0);for(var entry:bones.entrySet()){var bone=entry.getValue();var current=new org.joml.Quaternionf().rotationZYX(bone.zRot,bone.yRot,bone.xRot);var last=previous.put(entry.getKey(),current);if(last!=null)maximumStep=Math.max(maximumStep,2*(float)Math.acos(Math.min(1,Math.abs(current.dot(last)))));}}
            check(maximumStep<.12f,"Source motion interpolates without rotation jumps: "+kind);
            var hip=(org.joml.Vector3f)hipField.get(model);var origins=(java.util.Map<String,org.joml.Vector3f>)originsField.get(model);var torso=bones.get("torso");var rotation=new org.joml.Quaternionf().rotationZYX(torso.zRot,torso.yRot,torso.xRot);var joint=new org.joml.Vector3f(hip).sub(origins.get("torso")).rotate(rotation).add(torso.x,torso.y,torso.z);var left=bones.get("left_leg");var right=bones.get("right_leg");var pelvis=new org.joml.Vector3f(left.x+right.x,left.y+right.y,left.z+right.z).mul(.5f);check(joint.distance(pelvis)<.001f,"Torso and thighs share the same animated pelvis: "+kind+" delta="+joint.distance(pelvis)+" torso="+joint+" hip="+pelvis);
            actor.deathTime=1;model.setupAnim(actor,0,0,actor.tickCount+16,0,0);actor.deathTime=19;model.setupAnim(actor,0,0,actor.tickCount+300,0,0);var first=new java.util.HashMap<String,float[]>();for(var entry:bones.entrySet()){var b=entry.getValue();first.put(entry.getKey(),new float[]{b.xRot,b.yRot,b.zRot,b.x,b.y,b.z});}model.setupAnim(actor,0,0,actor.tickCount+300.8f,0,0);boolean stable=true;for(var entry:bones.entrySet()){var b=entry.getValue();var before=first.get(entry.getKey());stable&=Math.abs(b.xRot-before[0])+Math.abs(b.yRot-before[1])+Math.abs(b.zRot-before[2])+Math.abs(b.x-before[3])+Math.abs(b.y-before[4])+Math.abs(b.z-before[5])<.00001f;}actor.deathTime=0;check(stable,"Original death clip holds its final pose after the corpse timer cap: "+kind);
        }
    }
    @SuppressWarnings({"rawtypes","unchecked"}) void verifyRevision(Minecraft mc)throws Exception{
        var constructor=me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model.class.getDeclaredConstructor(String.class);constructor.setAccessible(true);var boneField=me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model.class.getDeclaredField("bones");boneField.setAccessible(true);var actor=mc.player;
        for(String kind:new String[]{"scourge_ghoul","scourge_skeleton"}){var model=(me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model)constructor.newInstance(kind);actor.deathTime=1;model.setupAnim(actor,0,0,actor.tickCount+.1f,0,0);actor.deathTime=19;model.setupAnim(actor,0,0,actor.tickCount+100,0,0);var bones=(java.util.Map<String,net.minecraft.client.model.geom.ModelPart>)boneField.get(model);var torso=bones.get("torso");var left=bones.get("left_leg");var right=bones.get("right_leg");var offset=new org.joml.Vector3f(left.x+right.x,left.y+right.y,left.z+right.z).mul(.5f);var hf=model.getClass().getDeclaredField("hip");hf.setAccessible(true);var hip=(org.joml.Vector3f)hf.get(model);var of=model.getClass().getDeclaredField("origins");of.setAccessible(true);var origins=(java.util.Map<String,org.joml.Vector3f>)of.get(model);var joint=new org.joml.Vector3f(hip).sub(origins.get("torso")).rotate(new org.joml.Quaternionf().rotationZYX(torso.zRot,torso.yRot,torso.xRot)).add(torso.x,torso.y,torso.z);check(joint.distance(offset)>1,"Death visibly separates upper and lower body: "+kind);actor.deathTime=0;}
        var model=(me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model)constructor.newInstance("scourge_skeleton");model.setupAnim(actor,0,0,actor.tickCount,0,0);var sf=me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model.class.getDeclaredField("states");sf.setAccessible(true);var state=((java.util.Map)sf.get(model)).get(actor);var attack=state.getClass().getDeclaredField("attackStart");attack.setAccessible(true);attack.setFloat(state,actor.tickCount);model.setupAnim(actor,0,0,actor.tickCount+15,0,0);var action=state.getClass().getDeclaredField("action");action.setAccessible(true);check(action.get(state).equals("melee"),"Skeleton attack retains its full motion beyond the vanilla swing");
        for(String kind:new String[]{"scourge_ghoul","scourge_zombie","scourge_skeleton","geist","abomination"}){var m=constructor.newInstance(kind);var eyes=m.getClass().getDeclaredField("eyeBoxes");eyes.setAccessible(true);check(!((java.util.List)eyes.get(m)).isEmpty(),"Scourge model has attached emissive smoking eyes: "+kind);try(var stream=mc.getResourceManager().getResource(new net.minecraft.resources.ResourceLocation("zombierool","textures/entities/blocky/"+kind+".png")).orElseThrow().open();var image=com.mojang.blaze3d.platform.NativeImage.read(stream)){int pixel=image.getPixelRGBA(64,64);check((pixel>>16&255)>(pixel&255)+70,"Scourge eye palette is blue: "+kind);}}
    }

