        var constructor=me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model.class.getDeclaredConstructor(String.class);constructor.setAccessible(true);var states=me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model.class.getDeclaredField("states");states.setAccessible(true);
        for(String kind:new String[]{"scourge_ghoul","scourge_zombie","scourge_skeleton"}){var mob=me.cryo.zombierool.init.ZombieroolModEntities.ZOMBIE.get().create(mc.level);mob.getAttribute(net.minecraft.world.entity.ai.attributes.Attributes.MOVEMENT_SPEED).setBaseValue(.25);var model=(me.cryo.zombierool.client.renderer.BlockyEnemyRenderer.Model)constructor.newInstance(kind);model.setupAnim(mob,0,.3f,1,0,0);var state=((java.util.Map)states.get(model)).get(mob);var action=state.getClass().getDeclaredField("action");action.setAccessible(true);check(action.get(state).equals("run"),"Actual sprint speed selects WoW run below the old limb-swing threshold: "+kind);}
