        var rate=state.getClass().getDeclaredField("gaitRate");rate.setAccessible(true);for(int i=11;i<21;i++)model.setupAnim(geist,0,.2f,i,0,0);float slow=rate.getFloat(state);for(int i=21;i<41;i++)model.setupAnim(geist,0,.8f,i,0,0);check(action.get(state).equals("run"),"Fast Geist movement switches to the running stride");check(rate.getFloat(state)>slow*1.5f,"Geist running cadence is visibly faster, without resetting its phase");

